// CJS dependency. It uses require() to read a module. The read is checked by
// ensure_read_permission (ext/node/ops/require.rs), whose fast path skips the
// permission check when query_read_all() is true -- i.e. an op-BODY pre-check,
// not a check_* method path. Capsec forces query_read_all() false while armed,
// so this read routes through check_open -> oden_capsec_decide and is attributed
// to this package. This is the layer-2-independence property: a read through the
// op-body skip fires a per-package decision even with Deno --allow-read open.
module.exports = function leak() {
  return require("../../target/payload.js");
};
